import json, math
import numpy as np
from sklearn.linear_model import Ridge
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.model_selection import GroupKFold, KFold
from sklearn.cluster import AgglomerativeClustering
from sklearn.metrics import adjusted_rand_score
from scipy.stats import spearmanr


def _f(v, nd=3):
    try:
        x = float(v)
    except Exception:
        return None
    if not math.isfinite(x):
        return None
    return round(x, nd)


def _get(d):
    X = np.asarray(d["X"], dtype=float)
    y = np.asarray(d["y"], dtype=float)
    g = d.get("groups")
    if g is None:
        g = np.array(["all"] * len(y))
    else:
        g = np.array([str(v) for v in g])
    return X, y, g


def _metrics(y, p, g):
    d = np.asarray(y, float) - np.asarray(p, float)
    per = [float(np.mean(np.abs(d[g == u]))) for u in np.unique(g)]
    return {"rmse": _f(math.sqrt(float(np.mean(d ** 2)))),
            "mae": _f(float(np.mean(np.abs(d)))),
            "gmae": _f(float(np.mean(per)))}


def _zfit(A):
    mu = A.mean(0)
    sd = A.std(0)
    sd = np.where(sd < 1e-12, 1.0, sd)
    return mu, sd


def _pool(p, lab):
    o = np.asarray(p, float).copy()
    for u in np.unique(lab):
        m = (lab == u)
        o[m] = float(o[m].mean())
    return o


def _cluster(X, k, tt_idx):
    Z = np.delete(X, [tt_idx], axis=1) if tt_idx is not None else X.copy()
    mu, sd = _zfit(Z)
    Z = (Z - mu) / sd
    n = Z.shape[0]
    k = int(max(1, min(int(k), n)))
    if k == 1:
        return np.zeros(n, dtype=int)
    return AgglomerativeClustering(n_clusters=k, linkage="ward").fit_predict(Z)


def _ridge(a):
    def b(Xa, ya, Xb):
        mu, sd = _zfit(Xa)
        m = Ridge(alpha=a).fit((Xa - mu) / sd, ya)
        return m.predict((Xb - mu) / sd)
    return b


def _hgb(Xa, ya, Xb):
    m = HistGradientBoostingRegressor(max_iter=250, learning_rate=0.08,
                                      max_leaf_nodes=31, l2_regularization=1.0,
                                      random_state=1729)
    m.fit(Xa, ya)
    return m.predict(Xb)


def _const(Xa, ya, Xb):
    return np.full(Xb.shape[0], float(np.mean(ya)))


def analyze(data, history, seed=1729):
    res = {"scope": "analysis only; no prediction returned",
           "data_use": "train and development X/y/groups supplied to analyze; clustering of feature rows without labels is transductive and reported as such"}
    try:
        tr = data["train"]
        dv = data["development"]
        fn = [str(s) for s in tr["feature_names"]]
        Xtr, ytr, gtr = _get(tr)
        Xdv, ydv, gdv = _get(dv)
        tt = fn.index("test_time") if "test_time" in fn else None
        res["shape"] = {"train_rows": int(Xtr.shape[0]), "dev_rows": int(Xdv.shape[0]),
                        "train_patients": int(len(np.unique(gtr))),
                        "dev_patients": int(len(np.unique(gdv))),
                        "n_features": len(fn), "test_time_index": tt}
    except Exception as e:
        return {"fatal_setup_error": str(e)[:300]}

    try:
        def decomp(y, g):
            us = np.unique(g)
            pm = np.array([float(y[g == u].mean()) for u in us])
            wv = float(np.mean([float(np.var(y[g == u])) for u in us]))
            return {"between_sd": _f(float(np.std(pm))),
                    "within_sd": _f(math.sqrt(max(wv, 0.0))),
                    "total_sd": _f(float(np.std(y))),
                    "pm_min": _f(float(pm.min())), "pm_max": _f(float(pm.max())),
                    "rows_per_patient": _f(float(len(y)) / max(1, len(us)), 1)}
        res["y_variance"] = {"train": decomp(ytr, gtr), "dev": decomp(ydv, gdv)}
    except Exception as e:
        res["y_variance_error"] = str(e)[:200]

    try:
        us = np.unique(gtr)
        idx = {u: k for k, u in enumerate(us)}
        pos = np.array([idx[u] for u in gtr])
        pm_y = np.array([float(ytr[gtr == u].mean()) for u in us])
        feats = []
        for j, name in enumerate(fn):
            col = Xtr[:, j]
            pmf = np.array([float(col[gtr == u].mean()) for u in us])
            tvar = float(np.var(col))
            icc = _f(float(np.var(pmf)) / tvar) if tvar > 1e-15 else None
            rb = rhob = None
            if float(np.std(pmf)) > 1e-12:
                rb = _f(float(np.corrcoef(pmf, pm_y)[0, 1]))
                try:
                    rhob = _f(float(spearmanr(pmf, pm_y).correlation))
                except Exception:
                    rhob = None
            cc = col - pmf[pos]
            cy = ytr - pm_y[pos]
            rw = None
            if float(np.std(cc)) > 1e-12 and float(np.std(cy)) > 1e-12:
                rw = _f(float(np.corrcoef(cc, cy)[0, 1]))
            feats.append({"f": name, "icc": icc, "rb": rb, "rhob": rhob, "rw": rw})
        res["features"] = feats
    except Exception as e:
        res["features_error"] = str(e)[:200]

    try:
        if tt is not None:
            us = np.unique(gtr)
            sl, r2 = [], []
            pm_y = []
            for u in us:
                m = (gtr == u)
                t = Xtr[m, tt]
                yy = ytr[m]
                pm_y.append(float(yy.mean()))
                if len(yy) > 2 and float(np.std(t)) > 1e-9:
                    A = np.vstack([t, np.ones_like(t)]).T
                    coef, _, _, _ = np.linalg.lstsq(A, yy, rcond=None)
                    pred = A.dot(coef)
                    ss = float(np.sum((yy - yy.mean()) ** 2))
                    sl.append(float(coef[0]))
                    r2.append(float(1.0 - np.sum((yy - pred) ** 2) / ss) if ss > 1e-12 else None)
            sl_a = np.array(sl, float)
            r2_a = np.array([v for v in r2 if v is not None], float)
            res["within_patient_time_trend"] = {
                "slope_mean": _f(float(sl_a.mean())) if sl_a.size else None,
                "slope_sd": _f(float(sl_a.std())) if sl_a.size else None,
                "slope_pos_frac": _f(float(np.mean(sl_a > 0))) if sl_a.size else None,
                "linear_r2_mean": _f(float(r2_a.mean())) if r2_a.size else None,
                "corr_slope_patientmean": _f(float(np.corrcoef(sl_a, np.array(pm_y[:sl_a.size]))[0, 1])) if sl_a.size > 2 else None}
    except Exception as e:
        res["time_trend_error"] = str(e)[:200]

    builders = {"const": _const, "ridge1": _ridge(1.0), "ridge10": _ridge(10.0),
                "ridge100": _ridge(100.0), "ridge1000": _ridge(1000.0), "hgb250": _hgb}

    try:
        us = np.unique(gtr)
        gk = GroupKFold(n_splits=int(min(7, len(us))))
        splits = list(gk.split(Xtr, ytr, gtr))
        cv = {}
        oof_store = {}
        for nm, b in builders.items():
            p = np.zeros(len(ytr))
            for a, t in splits:
                p[t] = b(Xtr[a], ytr[a], Xtr[t])
            oof_store[nm] = p
            cv[nm] = _metrics(ytr, p, gtr)
        res["patient_held_out_cv_train"] = cv
        pool = {}
        for nm in ["ridge10", "ridge100", "hgb250"]:
            if nm not in oof_store:
                continue
            po = np.zeros(len(ytr))
            pc = np.zeros(len(ytr))
            for a, t in splits:
                seg = oof_store[nm][t]
                po[t] = _pool(seg, gtr[t])
                pc[t] = _pool(seg, _cluster(Xtr[t], len(np.unique(gtr[t])), tt))
            pool[nm] = {"oracle_patient_pool": _metrics(ytr, po, gtr),
                        "cluster_pool_true_k": _metrics(ytr, pc, gtr)}
        res["pooling_effect_cv"] = pool
    except Exception as e:
        res["cv_error"] = str(e)[:200]

    try:
        kf = KFold(n_splits=5, shuffle=True, random_state=int(seed) % 100000)
        row_cv = {}
        for nm in ["ridge10", "hgb250"]:
            p = np.zeros(len(ytr))
            for a, t in kf.split(Xtr):
                p[t] = builders[nm](Xtr[a], ytr[a], Xtr[t])
            row_cv[nm] = _metrics(ytr, p, gtr)
        res["row_held_out_cv_train"] = row_cv
        res["optimism_note"] = "compare row_held_out_cv_train with patient_held_out_cv_train; a large gap indicates within-patient leakage rather than transferable signal"
    except Exception as e:
        res["row_cv_error"] = str(e)[:200]

    try:
        dev = {}
        dev_pred = {}
        for nm, b in builders.items():
            p = b(Xtr, ytr, Xdv)
            dev_pred[nm] = p
            dev[nm] = _metrics(ydv, p, gdv)
        res["dev_fit_on_train"] = dev
        dpool = {}
        for nm in ["ridge10", "ridge100", "hgb250"]:
            if nm not in dev_pred:
                continue
            e = {"oracle_patient_pool": _metrics(ydv, _pool(dev_pred[nm], gdv), gdv)}
            for k in [4, 7, 12, 20]:
                lab = _cluster(Xdv, k, tt)
                e["cluster_pool_k%d" % k] = _metrics(ydv, _pool(dev_pred[nm], lab), gdv)
            for w in [0.25, 0.5, 0.75]:
                base = float(np.mean(ytr))
                shr = w * np.asarray(dev_pred[nm], float) + (1.0 - w) * base
                e["shrink_to_train_mean_w%.2f" % w] = _metrics(ydv, shr, gdv)
            dpool[nm] = e
        res["dev_pooling_and_shrinkage"] = dpool
    except Exception as e:
        res["dev_error"] = str(e)[:200]

    try:
        cq = {}
        for k in [4, 7, 12, 20]:
            lab = _cluster(Xdv, k, tt)
            pur = 0.0
            for u in np.unique(lab):
                m = (lab == u)
                vals, cnt = np.unique(gdv[m], return_counts=True)
                pur += float(cnt.max())
            cq["k%d" % k] = {"ari": _f(float(adjusted_rand_score(gdv, lab))),
                             "purity": _f(pur / float(len(gdv)))}
        res["dev_transductive_cluster_quality"] = cq
        ages = Xdv[:, fn.index("age")] if "age" in fn else None
        sexes = Xdv[:, fn.index("sex")] if "sex" in fn else None
        if ages is not None and sexes is not None:
            combos = set(zip(ages.tolist(), sexes.tolist()))
            res["dev_age_sex_unique_combos"] = {"combos": int(len(combos)),
                                                "patients": int(len(np.unique(gdv)))}
        res["cluster_caveat"] = "true patient count is unknown at prediction time; k sensitivity above indicates whether a pooling wrapper is robust"
    except Exception as e:
        res["cluster_error"] = str(e)[:200]

    try:
        hs = []
        for h in (history or []):
            if not isinstance(h, dict):
                continue
            fa = h.get("facts") or {}
            hs.append({"task": str(h.get("task_id"))[:32], "kind": str((h.get("action") or {}).get("kind"))[:12],
                       "valid": bool(h.get("valid")), "loss": _f(fa.get("loss")), "gmae": _f(fa.get("group_mae"))}) 
        res["history_seen"] = hs[-8:]
    except Exception as e:
        res["history_error"] = str(e)[:200]

    try:
        s = json.dumps(res)
        if len(s.encode("utf-8")) > 7800 and "features" in res:
            fl = res["features"]
            keep = sorted(fl, key=lambda d: -abs(d.get("rb") or 0.0))[:8]
            res["features"] = keep
            res["features_trimmed"] = True
        s = json.dumps(res)
        if len(s.encode("utf-8")) > 8000:
            res.pop("history_seen", None)
            res.pop("features", None)
            res["trimmed"] = "dropped detail blocks to respect 8192-byte findings limit"
    except Exception as e:
        res["size_error"] = str(e)[:200]
    return res

import json
import math
import numpy as np


def find_col(names, key):
    for i in range(len(names)):
        if names[i] == key:
            return i
    return -1


def group_index(keys):
    order = []
    table = {}
    for i in range(len(keys)):
        k = keys[i]
        if k not in table:
            table[k] = []
            order.append(k)
        table[k].append(i)
    return order, table


def level_set(y, order, table):
    pm = []
    for k in order:
        ii = np.array(table[k], dtype=np.int64)
        pm.append(float(np.mean(y[ii])))
    pma = np.array(pm, dtype=float)
    return {
        "row_mean": float(np.mean(y)),
        "row_median": float(np.median(y)),
        "patient_mean": float(np.mean(pma)),
        "patient_median": float(np.median(pma)),
    }


def pooled_slope(t, y, order, table):
    num = 0.0
    den = 0.0
    slopes = []
    for k in order:
        ii = np.array(table[k], dtype=np.int64)
        if ii.shape[0] < 4:
            continue
        tt = t[ii]
        tc = tt - float(np.mean(tt))
        ss = float(np.sum(tc * tc))
        if ss <= 1e-9:
            continue
        yy = y[ii]
        b = float(np.sum(tc * (yy - float(np.mean(yy)))) / ss)
        slopes.append(b)
        num += ss * b
        den += ss
    if den <= 1e-12:
        return 0.0, slopes
    return num / den, slopes


def fit_predict(train, inputs, seed):
    notes = []
    fn = list(train["feature_names"])
    Xtr = np.asarray(train["X"], dtype=float)
    ytr = np.asarray(train["y"], dtype=float)
    gtr = [str(v) for v in train["groups"]]
    it = find_col(fn, "test_time")
    if it < 0:
        notes.append("fallback: no test_time column in train; time term disabled")
        ttr = np.zeros(Xtr.shape[0], dtype=float)
    else:
        ttr = Xtr[:, it]
    order, table = group_index(gtr)
    lv_keys = ["row_mean", "row_median", "patient_mean", "patient_median"]
    lam_grid = [0.0, 0.25, 0.5, 0.75, 1.0]
    sse = {}
    cnt = {}
    pmae = {}
    for lk in lv_keys:
        for lam in lam_grid:
            sse[(lk, lam)] = 0.0
            cnt[(lk, lam)] = 0
            pmae[(lk, lam)] = []
    for p in order:
        rest = []
        for k in order:
            if k != p:
                rest.extend(table[k])
        ridx = np.array(rest, dtype=np.int64)
        yo = ytr[ridx]
        to = ttr[ridx]
        go = [gtr[int(j)] for j in ridx]
        oo, ot = group_index(go)
        lvo = level_set(yo, oo, ot)
        bo, tmp = pooled_slope(to, yo, oo, ot)
        hi = np.array(table[p], dtype=np.int64)
        yh = ytr[hi]
        tc = ttr[hi] - float(np.mean(ttr[hi]))
        for lk in lv_keys:
            for lam in lam_grid:
                err = (lvo[lk] + lam * bo * tc) - yh
                sse[(lk, lam)] += float(np.sum(err * err))
                cnt[(lk, lam)] += int(hi.shape[0])
                pmae[(lk, lam)].append(float(np.mean(np.abs(err))))
    lopo = {}
    for lk in lv_keys:
        for lam in lam_grid:
            n = max(cnt[(lk, lam)], 1)
            lopo[(lk, lam)] = (
                math.sqrt(sse[(lk, lam)] / n),
                float(np.mean(np.array(pmae[(lk, lam)], dtype=float))),
            )
    base = lopo[("row_median", 0.0)]
    best = ("row_median", 0.0)
    for lk in lv_keys:
        for lam in lam_grid:
            cand = lopo[(lk, lam)]
            if cand[1] > 1.03 * base[1]:
                continue
            if cand[0] < lopo[best][0] - 1e-12:
                best = (lk, lam)
    lv = level_set(ytr, order, table)
    bfull, slopes = pooled_slope(ttr, ytr, order, table)
    level = lv[best[0]]
    lam = best[1]
    Xe = np.asarray(inputs["X"], dtype=float)
    fne = list(inputs["feature_names"])
    iae = find_col(fne, "age")
    ise = find_col(fne, "sex")
    ite = find_col(fne, "test_time")
    nrow = Xe.shape[0]
    if ite < 0:
        notes.append("fallback: no test_time in inputs; constant prediction used")
        te = np.zeros(nrow, dtype=float)
        lam = 0.0
    else:
        te = Xe[:, ite]
    center = np.full(nrow, float(np.mean(te)), dtype=float)
    sizes = []
    if lam > 0.0 and iae >= 0 and ise >= 0:
        keys = []
        for i in range(nrow):
            keys.append((round(float(Xe[i, iae]), 6), round(float(Xe[i, ise]), 6)))
        eo, et = group_index(keys)
        small = 0
        for k in eo:
            ii = np.array(et[k], dtype=np.int64)
            sizes.append(int(ii.shape[0]))
            if ii.shape[0] >= 20:
                center[ii] = float(np.mean(te[ii]))
            else:
                small += 1
        if len(eo) < 2:
            notes.append("fallback: transductive (age,sex) grouping gave fewer than 2 clusters; global centering used")
        if small > 0:
            notes.append("fallback: " + str(small) + " (age,sex) clusters had fewer than 20 rows; those rows used global centering")
    elif lam > 0.0:
        notes.append("fallback: age or sex missing in inputs; global centering used")
    pred = level + lam * bfull * (te - center)
    lo = float(np.min(ytr)) - 10.0
    hi2 = float(np.max(ytr)) + 10.0
    pred = np.clip(np.nan_to_num(pred, nan=level, posinf=hi2, neginf=lo), lo, hi2)
    sl = np.array(slopes, dtype=float)
    grid = {}
    for lk in lv_keys:
        for lam2 in lam_grid:
            grid[lk + "|" + str(lam2)] = [round(lopo[(lk, lam2)][0], 4), round(lopo[(lk, lam2)][1], 4)]
    findings = {
        "question": "does within-patient temporal drift of interpolated motor_UPDRS transfer to unseen patients via transductive (age,sex) centering of test_time",
        "chosen_level_estimator": best[0],
        "chosen_lambda": lam,
        "pooled_slope_per_day": round(float(bfull), 6),
        "n_patient_slopes": int(sl.shape[0]),
        "slope_positive_fraction": (round(float(np.mean(sl > 0.0)), 4) if sl.shape[0] > 0 else None),
        "slope_mean": (round(float(np.mean(sl)), 6) if sl.shape[0] > 0 else None),
        "slope_sd": (round(float(np.std(sl)), 6) if sl.shape[0] > 0 else None),
        "lopo_rmse_and_patient_mae_grid": grid,
        "lopo_constant_row_median_reference": [round(base[0], 4), round(base[1], 4)],
        "lopo_relative_rmse_gain_pct": round(100.0 * (base[0] - lopo[best][0]) / max(base[0], 1e-9), 4),
        "eval_cluster_sizes": sizes,
        "eval_cluster_count": len(sizes),
        "prediction_spread": [round(float(np.min(pred)), 4), round(float(np.max(pred)), 4)],
        "fallbacks_used": notes,
        "selection_rule": "leave-one-training-patient-out row RMSE, candidates rejected if LOPO equal-patient MAE exceeds 1.03x constant row-median reference",
        "transductive_use": "unlabeled evaluation rows grouped by exact (age,sex) solely to center test_time within a presumed patient; no evaluation labels, groups or row ids used",
        "caveat": "labels are linearly interpolated clinician ratings, so a fitted within-patient slope reflects interpolation between visits and is not an independent clinical measurement"
    }
    return {"prediction": [float(v) for v in pred], "findings": findings}

import json
import numpy as np

ORDER = ["row_median", "row_mean", "row_huber", "patient_mean_of_means", "patient_median_of_medians", "mid_row_mean_median"]


def _huber_center(y, iters=100):
    y = np.asarray(y, dtype=float)
    m = float(np.median(y))
    mad = float(np.median(np.abs(y - m)))
    s = 1.4826 * mad
    if (not np.isfinite(s)) or s <= 1e-9:
        return m
    d = 1.345 * s
    for _ in range(iters):
        r = y - m
        w = np.ones_like(r)
        big = np.abs(r) > d
        if np.any(big):
            w[big] = d / np.abs(r[big])
        sw = float(np.sum(w))
        if sw <= 0.0:
            return float(np.median(y))
        new = float(np.sum(w * y) / sw)
        if abs(new - m) < 1e-11:
            return new
        m = new
    return m


def _constants(y, g):
    y = np.asarray(y, dtype=float)
    g = np.asarray(g)
    uq = np.unique(g)
    pmean = np.array([float(np.mean(y[g == u])) for u in uq], dtype=float)
    pmed = np.array([float(np.median(y[g == u])) for u in uq], dtype=float)
    c = {}
    c["row_mean"] = float(np.mean(y))
    c["row_median"] = float(np.median(y))
    c["row_huber"] = float(_huber_center(y))
    c["patient_mean_of_means"] = float(np.mean(pmean))
    c["patient_median_of_medians"] = float(np.median(pmed))
    c["mid_row_mean_median"] = 0.5 * (c["row_mean"] + c["row_median"])
    return c


def _lopo(y, g):
    y = np.asarray(y, dtype=float)
    g = np.asarray(g)
    uq = np.unique(g)
    se = dict((k, 0.0) for k in ORDER)
    pm = dict((k, []) for k in ORDER)
    n = 0
    for u in uq:
        te = (g == u)
        tr = ~te
        if int(np.sum(tr)) < 2 or int(np.sum(te)) < 1:
            continue
        c = _constants(y[tr], g[tr])
        yt = y[te]
        n += int(yt.size)
        for k in ORDER:
            r = yt - c[k]
            se[k] += float(np.sum(r * r))
            pm[k].append(float(np.mean(np.abs(r))))
    grid = {}
    for k in ORDER:
        if n > 0 and len(pm[k]) > 0:
            grid[k] = [round(float(np.sqrt(se[k] / n)), 4), round(float(np.mean(pm[k])), 4)]
    return grid, int(uq.size), int(n)


def fit_predict(train, inputs, seed=0):
    fallbacks = []
    y = np.asarray(train["y"], dtype=float)
    if train.get("groups") is None:
        g = np.zeros(y.size, dtype=int)
        fallbacks.append("groups_missing_single_pseudo_patient")
    else:
        g = np.asarray(train["groups"])
    n_eval = len(inputs["X"])
    grid = {}
    n_pat = 0
    n_lopo = 0
    chosen = "row_median"
    rejected = []
    try:
        grid, n_pat, n_lopo = _lopo(y, g)
        if "row_median" not in grid:
            raise ValueError("lopo_grid_incomplete")
        ref_mae = grid["row_median"][1]
        best = None
        for k in ORDER:
            if k not in grid:
                continue
            if grid[k][1] > 1.03 * ref_mae:
                rejected.append(k)
                continue
            if best is None or grid[k][0] < grid[best][0] - 1e-12:
                best = k
        if best is None:
            fallbacks.append("all_candidates_rejected_by_equal_patient_mae_guard")
            chosen = "row_median"
        else:
            chosen = best
    except Exception as exc:
        fallbacks.append("lopo_selection_failed_" + type(exc).__name__)
        chosen = "row_median"
    try:
        consts = _constants(y, g)
    except Exception as exc:
        fallbacks.append("full_constants_failed_" + type(exc).__name__)
        consts = {"row_median": float(np.median(y))}
        chosen = "row_median"
    value = float(consts.get(chosen, float(np.median(y))))
    if not np.isfinite(value):
        fallbacks.append("non_finite_constant_replaced_by_row_median")
        value = float(np.median(y))
        chosen = "row_median"
    pred = [value] * n_eval
    gain = None
    try:
        if chosen in grid and "row_median" in grid:
            gain = round(100.0 * (grid["row_median"][0] - grid[chosen][0]) / grid["row_median"][0], 4)
    except Exception:
        gain = None
    findings = {
        "question": "which constant central tendency of interpolated motor_UPDRS transfers to unseen patients, and does LOPO ordering among constants predict held-out-patient ordering",
        "model_class": "constant_only_no_features_no_transduction",
        "transductive_use": "none; unlabeled evaluation X is used only for its row count",
        "selection_rule": "leave-one-training-patient-out row RMSE over a fixed 6-candidate constant list; candidate rejected if its LOPO equal-patient MAE exceeds 1.03x the row-median constant",
        "lopo_rmse_and_patient_mae_grid": grid,
        "lopo_patients": n_pat,
        "lopo_scored_rows": n_lopo,
        "candidate_constants_on_full_train": dict((k, round(float(v), 4)) for k, v in consts.items()),
        "chosen_constant_name": chosen,
        "chosen_constant_value": round(value, 4),
        "rejected_by_patient_mae_guard": rejected,
        "lopo_relative_rmse_gain_vs_row_median_pct": gain,
        "prediction_spread": [round(value, 4), round(value, 4)],
        "eval_rows": int(n_eval),
        "fallbacks_used": fallbacks,
        "caveat": "labels are linearly interpolated clinician ratings; these constants summarise that interpolated label distribution and carry no voice information. A LOPO advantage over 28 training patients need not transfer to 7 held-out patients, and the development/confirmation groups are small patient-level samples."
    }
    try:
        json.dumps(findings)
    except Exception:
        findings = {"chosen_constant_name": chosen, "chosen_constant_value": round(value, 4), "fallbacks_used": fallbacks + ["findings_not_json_serialisable"]}
    return {"prediction": pred, "findings": findings}

