import json, math
import numpy as np
from scipy.stats import skew
from sklearn.linear_model import Ridge
from sklearn.preprocessing import StandardScaler
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.model_selection import GroupKFold, KFold


def _rmse(a, b):
    a = np.asarray(a, float); b = np.asarray(b, float)
    return float(np.sqrt(np.mean((a - b) ** 2)))


def _patient_mae(err, groups):
    d = {}
    for e, g in zip(err, groups):
        d.setdefault(g, []).append(abs(float(e)))
    return float(np.mean([np.mean(v) for v in d.values()]))


class Const:
    def __init__(self, stat):
        self.stat = stat
    def fit(self, X, y):
        y = np.asarray(y, float)
        self.v = float(np.median(y)) if self.stat == 'median' else float(np.mean(y))
        return self
    def predict(self, X):
        return np.full(len(X), self.v)


class Lin:
    def __init__(self, cols, alpha, log_idx):
        self.cols = list(cols); self.alpha = alpha; self.log_idx = set(log_idx)
    def _f(self, X):
        Z = np.asarray(X, float)[:, self.cols].copy()
        for j, c in enumerate(self.cols):
            if c in self.log_idx:
                Z[:, j] = np.log(np.maximum(Z[:, j], 1e-12))
        return Z
    def fit(self, X, y):
        Z = self._f(X)
        self.sc = StandardScaler().fit(Z)
        self.m = Ridge(alpha=self.alpha).fit(self.sc.transform(Z), np.asarray(y, float))
        return self
    def predict(self, X):
        return self.m.predict(self.sc.transform(self._f(X)))


class Boost:
    def __init__(self, cols, seed):
        self.cols = list(cols); self.seed = seed
    def fit(self, X, y):
        self.m = HistGradientBoostingRegressor(max_iter=150, learning_rate=0.05, max_depth=3, min_samples_leaf=100, l2_regularization=10.0, random_state=self.seed)
        self.m.fit(np.asarray(X, float)[:, self.cols], np.asarray(y, float))
        return self
    def predict(self, X):
        return self.m.predict(np.asarray(X, float)[:, self.cols])


def _build(fn, Xtr, seed):
    names = [str(n).lower() for n in fn]
    p = Xtr.shape[1]
    def find(key, default):
        for i, n in enumerate(names):
            if key in n:
                return i
        return default
    age = find('age', 0); sex = find('sex', 1); tt = find('test_time', 2)
    demo = [age, sex]
    voice = [i for i in range(p) if i not in (age, sex, tt)]
    allc = list(range(p))
    log_idx = []
    for c in voice:
        col = Xtr[:, c]
        if np.all(col > 0) and skew(col) > 1.0:
            log_idx.append(c)
    cands = {}
    cands['median'] = Const('median')
    cands['mean'] = Const('mean')
    cands['demo_linear'] = Lin(demo, 1e-3, [])
    cands['demo_time_linear'] = Lin(demo + [tt], 1e-3, [])
    for a in (10.0, 100.0, 1000.0):
        cands['ridge_all_a%d' % int(a)] = Lin(allc, a, [])
        cands['ridge_log_a%d' % int(a)] = Lin(allc, a, log_idx)
    cands['ridge_voice_only_log_a100'] = Lin(voice, 100.0, log_idx)
    cands['hgb_shallow_all'] = Boost(allc, seed)
    cands['hgb_shallow_voice_only'] = Boost(voice, seed)
    return cands, log_idx, {'age': int(age), 'sex': int(sex), 'test_time': int(tt)}


def fit_predict(train, inputs, seed):
    seed = int(seed) if seed is not None else 0
    Xtr = np.asarray(train['X'], float); ytr = np.asarray(train['y'], float)
    Xte = np.asarray(inputs['X'], float)
    med = float(np.median(ytr))
    try:
        groups = np.asarray(train['groups'])
        fn = train['feature_names']
        cands, log_idx, idx = _build(fn, Xtr, seed)
        ng = len(set(groups.tolist()))
        gkf = GroupKFold(n_splits=min(7, ng))
        kf = KFold(n_splits=5, shuffle=True, random_state=seed)
        g_rmse = {}; g_pmae = {}; r_rmse = {}
        for name, mdl in cands.items():
            pred = np.zeros(len(ytr))
            for tr, te in gkf.split(Xtr, ytr, groups):
                pred[te] = mdl.fit(Xtr[tr], ytr[tr]).predict(Xtr[te])
            g_rmse[name] = round(_rmse(pred, ytr), 4)
            g_pmae[name] = round(_patient_mae(pred - ytr, groups), 4)
            pred2 = np.zeros(len(ytr))
            for tr, te in kf.split(Xtr):
                pred2[te] = mdl.fit(Xtr[tr], ytr[tr]).predict(Xtr[te])
            r_rmse[name] = round(_rmse(pred2, ytr), 4)
        keys = list(cands)
        order = sorted(g_rmse, key=lambda k: (g_rmse[k], keys.index(k)))
        best = order[0]
        model = cands[best].fit(Xtr, ytr)
        p = np.asarray(model.predict(Xte), float)
        lo, hi = float(np.min(ytr)), float(np.max(ytr))
        p = np.clip(p, lo, hi)
        bad = ~np.isfinite(p)
        p[bad] = med
        findings = {'fallback_used': False, 'selected_by_patient_cv_rmse': best, 'ranking': order[:6], 'group_cv_rmse': g_rmse, 'group_cv_patient_mae': g_pmae, 'row_cv_rmse': r_rmse, 'log_columns': [str(fn[c]) for c in log_idx], 'column_roles': idx, 'n_train_rows': int(len(ytr)), 'n_train_patients': int(ng), 'clip_range': [lo, hi], 'n_nonfinite_replaced': int(bad.sum()), 'note': 'selection used only train patients via GroupKFold; evaluation inputs used only for prediction'}
        return {'prediction': [float(v) for v in p], 'findings': findings}
    except Exception as e:
        return {'prediction': [med] * len(Xte), 'findings': {'fallback_used': True, 'fallback': 'train median', 'error': str(e)[:400]}}

import numpy as np
from sklearn.linear_model import Ridge
from sklearn.ensemble import HistGradientBoostingRegressor
from sklearn.model_selection import GroupKFold, KFold


def log_index(names):
    out = []
    for i, n in enumerate(names):
        low = str(n).lower()
        if ('jitter' in low) or ('shimmer' in low) or ('nhr' in low):
            out.append(i)
    return out


def apply_log(Z, lidx):
    Z = Z.copy()
    for i in lidx:
        Z[:, i] = np.log1p(np.maximum(Z[:, i], 0.0))
    return Z


def col_subset(names, mode):
    demo = []
    voice = []
    for i, n in enumerate(names):
        low = str(n).lower()
        if low in ('age', 'sex', 'test_time'):
            demo.append(i)
        else:
            voice.append(i)
    if mode == 'all':
        return list(range(len(names)))
    if mode == 'voice':
        return voice
    if mode == 'demo':
        return [i for i in demo if str(names[i]).lower() != 'test_time']
    if mode == 'demo_time':
        return demo
    return list(range(len(names)))


def make_specs():
    specs = []
    specs.append({'name': 'median', 'kind': 'const', 'stat': 'median'})
    specs.append({'name': 'mean', 'kind': 'const', 'stat': 'mean'})
    specs.append({'name': 'lin_age_sex', 'kind': 'ridge', 'cols': 'demo', 'alpha': 0.001, 'log': False})
    specs.append({'name': 'lin_age_sex_time', 'kind': 'ridge', 'cols': 'demo_time', 'alpha': 0.001, 'log': False})
    for a in (10.0, 100.0, 1000.0):
        specs.append({'name': 'ridge_all_a%g' % a, 'kind': 'ridge', 'cols': 'all', 'alpha': a, 'log': False})
        specs.append({'name': 'ridge_all_log_a%g' % a, 'kind': 'ridge', 'cols': 'all', 'alpha': a, 'log': True})
    specs.append({'name': 'ridge_voice_log_a100', 'kind': 'ridge', 'cols': 'voice', 'alpha': 100.0, 'log': True})
    specs.append({'name': 'hgb_shallow_all', 'kind': 'hgb', 'cols': 'all'})
    specs.append({'name': 'hgb_shallow_voice', 'kind': 'hgb', 'cols': 'voice'})
    return specs


def fit_spec(spec, X, y, names, seed):
    kind = spec['kind']
    if kind == 'const':
        if spec['stat'] == 'median':
            c = float(np.median(y))
        else:
            c = float(np.mean(y))

        def pred_const(Xe):
            return np.full(Xe.shape[0], c)
        return pred_const
    cols = col_subset(names, spec['cols'])
    sub_names = [names[i] for i in cols]
    lidx = log_index(sub_names)
    if kind == 'ridge':
        Z = X[:, cols]
        if spec['log']:
            Z = apply_log(Z, lidx)
        mu = Z.mean(axis=0)
        sd = Z.std(axis=0)
        sd = np.where(sd > 0, sd, 1.0)
        model = Ridge(alpha=spec['alpha'])
        model.fit((Z - mu) / sd, y)

        def pred_ridge(Xe):
            Ze = Xe[:, cols]
            if spec['log']:
                Ze = apply_log(Ze, lidx)
            return model.predict((Ze - mu) / sd)
        return pred_ridge
    if kind == 'hgb':
        model = HistGradientBoostingRegressor(max_iter=120, learning_rate=0.05, max_depth=3, max_leaf_nodes=8, min_samples_leaf=150, l2_regularization=10.0, random_state=seed)
        model.fit(X[:, cols], y)

        def pred_hgb(Xe):
            return model.predict(Xe[:, cols])
        return pred_hgb
    raise ValueError('unknown spec kind')


def group_mae(y, p, g):
    vals = []
    for gid in np.unique(g):
        m = g == gid
        vals.append(float(np.mean(np.abs(y[m] - p[m]))))
    return float(np.mean(vals))


def evaluate(spec, X, y, g, names, seed):
    n = len(y)
    ng = len(np.unique(g))
    k = min(7, ng)
    oof = np.zeros(n)
    gkf = GroupKFold(n_splits=k)
    for tr, te in gkf.split(X, y, g):
        f = fit_spec(spec, X[tr], y[tr], names, seed)
        oof[te] = f(X[te])
    grmse = float(np.sqrt(np.mean((y - oof) ** 2)))
    gmae = group_mae(y, oof, g)
    oof_r = np.zeros(n)
    kf = KFold(n_splits=5, shuffle=True, random_state=seed)
    for tr, te in kf.split(X):
        f = fit_spec(spec, X[tr], y[tr], names, seed)
        oof_r[te] = f(X[te])
    rrmse = float(np.sqrt(np.mean((y - oof_r) ** 2)))
    return grmse, gmae, rrmse


def between_patient_fraction(y, g):
    tot = float(np.var(y))
    if tot <= 0:
        return 0.0
    means = np.zeros(len(y))
    for gid in np.unique(g):
        m = g == gid
        means[m] = np.mean(y[m])
    return float(np.var(means) / tot)


def fit_predict(train, inputs, seed):
    if seed is None:
        seed = 0
    seed = int(seed)
    names = list(train['feature_names'])
    X = np.asarray(train['X'], dtype=float)
    y = np.asarray(train['y'], dtype=float)
    g = np.asarray(train['groups'])
    Xe = np.asarray(inputs['X'], dtype=float)
    specs = make_specs()
    table = []
    for spec in specs:
        try:
            grmse, gmae, rrmse = evaluate(spec, X, y, g, names, seed)
            table.append({'name': spec['name'], 'ok': True, 'group_rmse': round(grmse, 4), 'group_mae': round(gmae, 4), 'row_rmse': round(rrmse, 4), 'row_minus_group_gap': round(rrmse - grmse, 4)})
        except Exception as err:
            table.append({'name': spec['name'], 'ok': False, 'error': str(err)[:200]})
    ok = [t for t in table if t['ok'] and np.isfinite(t['group_rmse'])]
    fallback = False
    chosen = None
    pred = None
    refit_error = None
    if len(ok) > 0:
        best = min(ok, key=lambda t: t['group_rmse'])
        chosen = best['name']
        try:
            spec = [s for s in specs if s['name'] == chosen][0]
            f = fit_spec(spec, X, y, names, seed)
            pred = np.asarray(f(Xe), dtype=float)
        except Exception as err:
            refit_error = str(err)[:200]
            pred = None
    if pred is None or pred.shape[0] != Xe.shape[0]:
        fallback = True
        pred = np.full(Xe.shape[0], float(np.median(y)))
    bad = ~np.isfinite(pred)
    n_bad = int(bad.sum())
    if n_bad > 0:
        pred[bad] = float(np.median(y))
    med_row = [t for t in ok if t['name'] == 'median']
    med_group_rmse = med_row[0]['group_rmse'] if len(med_row) > 0 else None
    findings = {
        'selection_rule': 'lowest 7-fold GroupKFold RMSE over train patients, ties earliest in candidate order',
        'chosen': chosen,
        'fallback_used_train_median': fallback,
        'refit_error': refit_error,
        'n_nonfinite_replaced': n_bad,
        'n_train_rows': int(X.shape[0]),
        'n_train_patients': int(len(np.unique(g))),
        'n_eval_rows': int(Xe.shape[0]),
        'train_y_median': round(float(np.median(y)), 4),
        'train_y_mean': round(float(np.mean(y)), 4),
        'train_y_std': round(float(np.std(y)), 4),
        'between_patient_variance_fraction_train': round(between_patient_fraction(y, g), 4),
        'median_group_rmse': med_group_rmse,
        'candidates': table,
        'transductive_use': 'none; all scaling and selection statistics computed from train rows only',
        'note': 'row-level CV is patient-leaky and shown only as a contrast to patient-held-out CV; no evaluation labels used'
    }
    return {'prediction': [float(v) for v in pred], 'findings': findings}

import numpy as np, json, math
from scipy.stats import spearmanr
from sklearn.linear_model import Ridge

def _r(x, d=3):
    try:
        x = float(x)
    except Exception:
        return None
    return round(x, d) if math.isfinite(x) else None

def _clean(o):
    if isinstance(o, dict):
        return {str(k): _clean(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [_clean(v) for v in o]
    if isinstance(o, (np.floating, float)):
        return _r(o)
    if isinstance(o, (np.integer,)):
        return int(o)
    return o

def analyze(data, history, seed):
    rng = np.random.RandomState(int(seed) if seed is not None else 0)
    fn = list(data['train']['feature_names'])
    idx = {n: i for i, n in enumerate(fn)}
    voice = [n for n in fn if n not in ('age', 'sex', 'test_time')]
    logcols = [n for n in voice if any(k in n.lower() for k in ('jitter', 'shimmer', 'nhr'))]
    def arr(split):
        d = data[split]
        return (np.asarray(d['X'], float), np.asarray(d['y'], float),
                np.asarray([str(g) for g in d['groups']]), [str(r) for r in d['row_ids']])
    Xtr, ytr, gtr, rtr = arr('train')
    Xdv, ydv, gdv, rdv = arr('development')
    def patients(X, y, g, tag):
        P = []
        for p in sorted(set(g.tolist())):
            m = g == p
            Xp = X[m].copy()
            for n in logcols:
                j = idx[n]
                Xp[:, j] = np.log(np.maximum(Xp[:, j], 1e-9))
            tt = X[m, idx['test_time']]
            yp = y[m]
            slope = float(np.polyfit(tt, yp, 1)[0]) if (m.sum() > 2 and tt.std() > 0) else 0.0
            P.append(dict(id=p, split=tag, demo=[Xp[:, idx['age']].mean(), Xp[:, idx['sex']].mean()],
                          mean=[Xp[:, idx[n]].mean() for n in voice], std=[Xp[:, idx[n]].std() for n in voice],
                          ymean=float(yp.mean()), ystd=float(yp.std()), slope=slope, n=int(m.sum()),
                          tspan=float(tt.max() - tt.min()), yrows=yp))
        return P
    Ptr = patients(Xtr, ytr, gtr, 'train')
    Pdv = patients(Xdv, ydv, gdv, 'dev')
    Pall = Ptr + Pdv
    def feats(P, kind):
        if kind == 'const':
            return np.zeros((len(P), 0))
        rows = []
        for p in P:
            v = []
            if 'demo' in kind: v += list(p['demo'])
            if 'mean' in kind: v += list(p['mean'])
            if 'std' in kind: v += list(p['std'])
            rows.append(v)
        return np.asarray(rows, float)
    def fit_pred(Ftr, y_, Fte, alpha):
        if Ftr.shape[1] == 0:
            return np.full(len(Fte), float(y_.mean()))
        mu = Ftr.mean(0); sd = Ftr.std(0); sd[sd == 0] = 1.0
        return Ridge(alpha=alpha).fit((Ftr - mu) / sd, y_).predict((Fte - mu) / sd)
    def loo(F, ym, alpha):
        n = len(ym); pred = np.zeros(n)
        for i in range(n):
            m = np.ones(n, bool); m[i] = False
            pred[i] = fit_pred(F[m], ym[m], F[i:i + 1], alpha)[0]
        return pred
    models = [('const', 'const', 0.0), ('demo_a10', 'demo', 10.0), ('mean_a100', 'mean', 100.0),
              ('mean_a1000', 'mean', 1000.0), ('demo_mean_std_a1000', 'demo mean std', 1000.0)]
    def scores(P, pred):
        ym = np.array([p['ymean'] for p in P])
        sq_pat = (ym - pred) ** 2
        sq_rows = np.array([np.sum((p['yrows'] - pred[i]) ** 2) for i, p in enumerate(P)])
        nrows = np.array([p['n'] for p in P], float)
        pat_mae = np.array([np.mean(np.abs(p['yrows'] - pred[i])) for i, p in enumerate(P)])
        return dict(patient_rmse=math.sqrt(sq_pat.mean()), row_rmse=math.sqrt(sq_rows.sum() / nrows.sum()),
                    equal_patient_mae=float(pat_mae.mean())), sq_rows, nrows
    def boot_ci(sq_a, sq_b, nrows, B=1000):
        n = len(nrows); diffs = []
        for _ in range(B):
            s = rng.randint(0, n, n)
            diffs.append(math.sqrt(sq_a[s].sum() / nrows[s].sum()) - math.sqrt(sq_b[s].sum() / nrows[s].sum()))
        return [float(np.percentile(diffs, 2.5)), float(np.percentile(diffs, 97.5))]
    out = {'note': 'patient-level aggregate analysis; LOO = leave-one-patient-out on patient means with ridge on standardized aggregates; development labels ARE used here (analysis only), so any downstream selection informed by these numbers is development-tuned, not independent; no evaluation score is produced',
           'n_patients': {'train': len(Ptr), 'dev': len(Pdv)}, 'log_cols': logcols}
    ym_all = np.array([p['ymean'] for p in Pall])
    tot_var = float(np.var(np.concatenate([p['yrows'] for p in Pall])))
    within = float(np.sum([p['n'] * p['ystd'] ** 2 for p in Pall]) / np.sum([p['n'] for p in Pall]))
    sl = [p['slope'] for p in Pall]
    out['target_structure'] = {'between_patient_var_share_all35': (1.0 - within / tot_var) if tot_var > 0 else None,
                               'ymean_sd_across_patients': float(ym_all.std()),
                               'median_within_patient_sd': float(np.median([p['ystd'] for p in Pall])),
                               'slope_per_day_median': float(np.median(sl)),
                               'slope_per_day_iqr': [float(np.percentile(sl, 25)), float(np.percentile(sl, 75))],
                               'median_tspan_days': float(np.median([p['tspan'] for p in Pall]))}
    res = {}
    for setname, P in (('loo_train28', Ptr), ('loo_all35', Pall)):
        ym = np.array([p['ymean'] for p in P]); tab = {}
        base_sq = None; base_n = None
        for name, kind, a in models:
            pred = loo(feats(P, kind), ym, a)
            sc, sq, nr = scores(P, pred)
            if name == 'const':
                base_sq, base_n = sq, nr
            else:
                sc['row_rmse_minus_const_boot95'] = boot_ci(sq, base_sq, nr)
            tab[name] = sc
        res[setname] = tab
    out['patient_held_out'] = res
    ym_tr = np.array([p['ymean'] for p in Ptr]); tr_dev = {}
    for name, kind, a in models:
        pred = fit_pred(feats(Ptr, kind), ym_tr, feats(Pdv, kind), a)
        sc, _, _ = scores(Pdv, pred)
        sc['per_patient_bias'] = [float(pred[i] - p['ymean']) for i, p in enumerate(Pdv)]
        tr_dev[name] = sc
    out['train28_to_dev7_true_groups'] = {'dev_patient_ids': [p['id'] for p in Pdv], 'dev_ymeans': [p['ymean'] for p in Pdv],
                                          'dev_age_sex': [p['demo'] for p in Pdv], 'models': tr_dev}
    perm = {}
    for name, kind, a in (('mean_a1000', 'mean', 1000.0), ('demo_mean_std_a1000', 'demo mean std', 1000.0), ('demo_a10', 'demo', 10.0)):
        F = feats(Pall, kind)
        obs = math.sqrt(np.mean((ym_all - loo(F, ym_all, a)) ** 2))
        cnt = 0; B = 300; null = []
        for _ in range(B):
            yp = rng.permutation(ym_all)
            v = math.sqrt(np.mean((yp - loo(F, yp, a)) ** 2)); null.append(v)
            if v <= obs: cnt += 1
        perm[name] = {'obs_patient_rmse': obs, 'perm_p_leq': (cnt + 1) / (B + 1), 'null_median': float(np.median(null)), 'B': B}
    perm['const_patient_rmse_all35'] = math.sqrt(np.mean((ym_all - loo(feats(Pall, 'const'), ym_all, 0.0)) ** 2))
    out['permutation_all35'] = perm
    Fm = feats(Pall, 'demo mean'); names = ['age', 'sex'] + ['mean_' + n for n in voice]
    rs = [spearmanr(Fm[:, j], ym_all)[0] for j in range(Fm.shape[1])]
    maxnull = []
    for _ in range(1000):
        yp = rng.permutation(ym_all)
        maxnull.append(max(abs(spearmanr(Fm[:, j], yp)[0]) for j in range(Fm.shape[1])))
    order = np.argsort(-np.abs(np.nan_to_num(np.array(rs, float))))
    out['spearman_patient_level_all35'] = {'top': [[names[j], float(rs[j])] for j in order[:8]],
                                           'max_abs_r_null_q95': float(np.percentile(maxnull, 95)),
                                           'max_abs_r_null_q50': float(np.percentile(maxnull, 50))}
    pos = {r: i for i, r in enumerate(rdv)}
    hist = []
    for h in (history or []):
        if not isinstance(h, dict):
            continue
        try:
            pr = h.get('prediction')
            if not h.get('valid') or not pr:
                continue
            pv = np.full(len(rdv), np.nan)
            for r, v in zip(pr.get('row_ids', []), pr.get('prediction', [])):
                if str(r) in pos:
                    pv[pos[str(r)]] = float(v)
            if np.isnan(pv).any():
                continue
            e = pv - ydv
            hist.append({'task': str(h.get('task_id'))[:16], 'action': str(h.get('action_id'))[:12], 'row_rmse': math.sqrt(np.mean(e ** 2)),
                         'per_patient_bias': [float(e[gdv == p['id']].mean()) for p in Pdv],
                         'per_patient_mae': [float(np.abs(e[gdv == p['id']]).mean()) for p in Pdv],
                         'pred_sd_within_patient_median': float(np.median([pv[gdv == p['id']].std() for p in Pdv]))})
        except Exception as ex:
            hist.append({'task': str(h.get('task_id', '?'))[:16], 'error': str(ex)[:80]})
    out['dev_history_breakdown'] = hist[:10]
    out = _clean(out)
    s = json.dumps(out)
    if len(s.encode('utf-8')) > 8000:
        out['dev_history_breakdown'] = [{'task': h.get('task'), 'row_rmse': h.get('row_rmse'), 'per_patient_bias': h.get('per_patient_bias')} for h in out['dev_history_breakdown']]
        s = json.dumps(out)
    if len(s.encode('utf-8')) > 8000:
        out.pop('spearman_patient_level_all35', None); s = json.dumps(out)
    if len(s.encode('utf-8')) > 8000:
        out.pop('dev_history_breakdown', None)
    return out
